def rtree(rng, n, p=0.0):
    L = [-1] * n
    R = [-1] * n
    free = [(0, 0), (0, 1)]
    for i in range(1, n):
        if rng.random() < p:
            idx = len(free) - 1 - (rng.randint(0, 1) if len(free) > 1 else 0)
            u, s = free.pop(idx)
        else:
            idx = rng.randrange(len(free))
            free[idx], free[-1] = free[-1], free[idx]
            u, s = free.pop()
        if s == 0:
            L[u] = i
        else:
            R[u] = i
        free.append((i, 0))
        free.append((i, 1))
    return L, R

def ser(L, R, vals):
    out = []
    q = [0]
    qi = 0
    while qi < len(q):
        u = q[qi]
        qi += 1
        if u < 0:
            out.append('null')
            continue
        out.append(str(vals[u]))
        q.append(L[u])
        q.append(R[u])
    while out and out[-1] == 'null':
        out.pop()
    return ' '.join(out)

def height(L, R):
    n = len(L)
    d = [1] * n
    for u in range(n):
        if L[u] >= 0:
            d[L[u]] = d[u] + 1
        if R[u] >= 0:
            d[R[u]] = d[u] + 1
    return max(d)

